      if (wr_en && !full) begin
        fifo_mem[wr_ptr] <= wr_data;
        wr_ptr <= wr_ptr + 1'b1;
        count <= count + 1'b1;
        empty <= 1'b0;
        if (count == DEPTH - 1)
          full <= 1'b1;
      end
