    if (!rst_n) begin
      rd_ptr <= '0;
      count <= '0;
      empty <= 1'b1;
      full <= 1'b0;
    end else begin
      if (rd_ack && !empty) begin
        rd_ptr <= rd_ptr + 1'b1;
        count <= count - 1'b1;
        full <= 1'b0;
        if (count == 1)
          empty <= 1'b1;
      end
    end
  end

endmodule

